SELECT *, MIN(cost) OVER (PARTITION BY supplier_id ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_cost, SUM(cost) OVER (PARTITION BY supplier_id ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_cost, MAX(cost) OVER (PARTITION BY supplier_id ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_cost, COUNT(cost) OVER (PARTITION BY supplier_id ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_cost FROM products;
